import{_ as r,o as t,c as o,a2 as i}from"./chunks/framework.DpbdyYUv.js";const e="/unit_devlab_esp32_examples/assets/IMG_9435.BbtJWsaB.jpg",d="/unit_devlab_esp32_examples/assets/firmware-merged-pulsar-stick-v2.CfINtUv9.png",l="/unit_devlab_esp32_examples/assets/IMG_9437.-svAODA9.jpg",s="/unit_devlab_esp32_examples/assets/IMG_9436.DXCfcHNg.jpg",n="/unit_devlab_esp32_examples/assets/IMG_9439.DGH1RLVT.jpg",c="/unit_devlab_esp32_examples/assets/IMG_9440.CwiaHW01.jpg",p="/unit_devlab_esp32_examples/assets/IMG_9441.mGO4UHjL.jpg",P=JSON.parse('{"title":"Lab 7: PULSAR Stick — Red Zigbee","description":"","frontmatter":{},"headers":[],"relativePath":"examples/labs07-zigbee-pulsar-stick.md","filePath":"examples/labs07-zigbee-pulsar-stick.md"}'),g={name:"examples/labs07-zigbee-pulsar-stick.md"};function m(u,a,b,h,S,_){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="lab-7-pulsar-stick-—-red-zigbee" tabindex="-1">Lab 7: PULSAR Stick — Red Zigbee <a class="header-anchor" href="#lab-7-pulsar-stick-—-red-zigbee" aria-label="Permalink to &quot;Lab 7: PULSAR Stick — Red Zigbee&quot;">​</a></h1><p>La <strong>PULSAR Stick</strong> es un desarrollo pensado para facilitar la experiencia con microcontroladores a la hora de realizar conexiones. Integra un conector de salida rápida <strong>Qwiic I²C</strong> para implementar sensores, lo que facilita la comprensión de los conceptos.</p><p>El formato &quot;stick&quot; es un formato de desarrollo pensado como banco de pruebas I²C, con un botón I²C que agiliza el desarrollo. Consta de un sistema principal <strong>PULSAR C6</strong>, elaborado con una conexión I²C a un display OLED y una salida Qwiic (<code>SDA</code> en el pin 6, <code>SCL</code> en el pin 7), con el fin de facilitar la comprensión de los conceptos. Además, se considera <strong>Zigbee</strong> como una experiencia compartida para este producto.</p><p><img src="'+e+'" alt="PULSAR Stick"></p><h3 id="pantalla-oled-de-estado" tabindex="-1">Pantalla OLED de estado <a class="header-anchor" href="#pantalla-oled-de-estado" aria-label="Permalink to &quot;Pantalla OLED de estado&quot;">​</a></h3><p>El display OLED integrado reporta en todo momento el estado del dispositivo, sin depender de un depurador ni del monitor serial:</p><ul><li><code>ZIGBEE SWITCH</code> — rol/función activa del firmware cargado.</li><li><code>NETWORK: JOINED</code> — estado de la unión a la red Zigbee.</li><li><code>MODE: POWER</code> — modo de operación configurado.</li><li><code>SHORT: ON/OFF</code> — acción asignada a la pulsación corta del botón.</li></ul><p>Esta lectura en pantalla permite comprobar el rol cargado y el estado de la red sin depender de un depurador ni del monitor serial.</p><h2 id="objetivo-del-taller" tabindex="-1">Objetivo del taller <a class="header-anchor" href="#objetivo-del-taller" aria-label="Permalink to &quot;Objetivo del taller&quot;">​</a></h2><p>Configurar una red Zigbee con dispositivos PULSAR, asignar los firmware merged de Gateway, Switch y Lamp, y validar el control de las lámparas desde una PULSAR Stick configurada como interruptor.</p><h2 id="resultados-del-aprendizaje" tabindex="-1">Resultados del aprendizaje <a class="header-anchor" href="#resultados-del-aprendizaje" aria-label="Permalink to &quot;Resultados del aprendizaje&quot;">​</a></h2><p>Al finalizar, los participantes podrán:</p><ul><li>Identificar las funciones de Gateway, Switch y Lamp dentro de la red Zigbee de la práctica.</li><li>Seleccionar el binario merged correcto para un Gateway ESP32-C5 y para cada PULSAR Stick ESP32-C6.</li><li>Cargar los firmware mediante Panel Loader y comprobar el rol activo en la pantalla OLED.</li><li>Incorporar las PULSAR Stick a la red y verificar el estado <code>NETWORK: JOINED</code>.</li><li>Generar comandos desde una única Stick configurada como Switch y observar la respuesta de las Stick configuradas como Lamp.</li><li>Reconocer las funciones de coordinador, enrutador y dispositivo final dentro de una red Zigbee.</li><li>Usar el firmware Toolbox como herramienta de diagnóstico cuando sea necesario validar el hardware.</li><li>Registrar evidencia del rol, la unión a la red y la respuesta de las lámparas durante la prueba final.</li></ul><h2 id="metodologia" tabindex="-1">Metodología <a class="header-anchor" href="#metodologia" aria-label="Permalink to &quot;Metodología&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Etapa</th><th>Asignación de roles</th><th>Dinámica</th></tr></thead><tbody><tr><td><strong>Etapa 1: Preparación</strong></td><td>1 Gateway · 1 Switch · las demás PULSAR Stick como Lamp</td><td>Cada integrante descarga y carga el binario merged correspondiente a su placa mediante Panel Loader.</td></tr><tr><td><strong>Etapa 2: Integración Zigbee</strong></td><td>Roles fijos durante la prueba</td><td>El equipo inicia el Gateway, incorpora las PULSAR Stick a la red y comprueba <code>NETWORK: JOINED</code> en cada pantalla.</td></tr><tr><td><strong>Etapa 3: Validación</strong></td><td>Switch y Lamp</td><td>Se generan comandos desde la única Stick Switch y se verifica la respuesta de todas las Stick Lamp. Toolbox se utiliza solo si es necesario diagnosticar hardware.</td></tr></tbody></table><h2 id="materiales-para-el-taller" tabindex="-1">Materiales para el taller <a class="header-anchor" href="#materiales-para-el-taller" aria-label="Permalink to &quot;Materiales para el taller&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Producto</th><th>Cantidad</th><th>Función</th></tr></thead><tbody><tr><td>Gateway ESP32-C5</td><td>1 por red</td><td>Crear y administrar la red Zigbee</td></tr><tr><td>PULSAR Stick ESP32-C6</td><td>1 como Switch</td><td>Enviar los comandos de control</td></tr><tr><td>PULSAR Stick ESP32-C6</td><td>Las demás como Lamp</td><td>Recibir los comandos y controlar las lámparas</td></tr><tr><td>Módulo de lámpara Qwiic</td><td>1 por Stick Lamp</td><td>Mostrar la respuesta al comando Zigbee</td></tr><tr><td>Cable USB de datos</td><td>1 por placa durante la carga</td><td>Programación mediante Panel Loader</td></tr></tbody></table><h2 id="carga-de-firmware-—-panel-loader" tabindex="-1">Carga de firmware — Panel Loader <a class="header-anchor" href="#carga-de-firmware-—-panel-loader" aria-label="Permalink to &quot;Carga de firmware — Panel Loader&quot;">​</a></h2><p>Los dispositivos de la práctica se programan desde el navegador con <strong>Panel Loader</strong>, sin instalar <code>esptool</code> ni drivers adicionales. Elige el firmware que corresponda al microcontrolador y a la función de cada placa:</p><p><strong><a href="https://unit-electronics-labs.github.io/unit_microsupport_labs/" target="_blank" rel="noreferrer">Abrir Panel Loader</a></strong></p><blockquote><p>Requiere un navegador con soporte WebSerial/WebUSB (Chrome o Edge de escritorio). Firefox y Safari no son compatibles.</p></blockquote><h3 id="descarga-de-firmware-merged" tabindex="-1">Descarga de firmware merged <a class="header-anchor" href="#descarga-de-firmware-merged" aria-label="Permalink to &quot;Descarga de firmware merged&quot;">​</a></h3><p>Estos binarios ya contienen las imágenes necesarias en un solo archivo y están listos para seleccionarse desde Panel Loader:</p><p><img src="'+d+'" alt="Aplicación de los firmware merged para PULSAR Stick"></p><table tabindex="0"><thead><tr><th>Firmware</th><th>Aplicación</th><th>Archivo de descarga</th></tr></thead><tbody><tr><td>Gateway</td><td>Para ESP32-C5</td><td><a href="/unit_devlab_esp32_examples/examples/firmware/pulsar_stick_gateway_merged.bin">Descargar <code>pulsar_stick_gateway_merged.bin</code></a></td></tr><tr><td>Switch</td><td>Para una sola Stick con ESP32-C6</td><td><a href="/unit_devlab_esp32_examples/examples/firmware/pulsar_stick_switch_merged.bin">Descargar <code>pulsar_stick_switch_merged.bin</code></a></td></tr><tr><td>Lamp</td><td>Para todas las PULSAR Stick</td><td><a href="/unit_devlab_esp32_examples/examples/firmware/pulsar_stick_lamp_merged.bin">Descargar <code>pulsar_stick_lamp_merged.bin</code></a></td></tr><tr><td>Toolbox</td><td>Herramienta de pruebas para validación de hardware</td><td><a href="/unit_devlab_esp32_examples/examples/firmware/pulsar_stick_TOOLBOX_merged.bin">Descargar <code>pulsar_stick_TOOLBOX_merged.bin</code></a></td></tr></tbody></table><h3 id="protocolo-de-carga" tabindex="-1">Protocolo de carga <a class="header-anchor" href="#protocolo-de-carga" aria-label="Permalink to &quot;Protocolo de carga&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pestaña del panel</th><th>Protocolo</th><th>Placa de esta práctica</th></tr></thead><tbody><tr><td><strong>ESP32</strong></td><td>Serie / esptool-js</td><td><strong>Gateway ESP32-C5</strong> y PULSAR Stick <strong>ESP32-C6</strong> con firmware Switch, Lamp o Toolbox</td></tr></tbody></table><h3 id="pasos-para-cargar-un-firmware" tabindex="-1">Pasos para cargar un firmware <a class="header-anchor" href="#pasos-para-cargar-un-firmware" aria-label="Permalink to &quot;Pasos para cargar un firmware&quot;">​</a></h3><ol><li>Abre el enlace del Panel Loader y selecciona la pestaña <strong>ESP32</strong>.</li><li>En <strong>Firmware</strong>, da clic en <strong>Seleccionar firmware</strong> y elige el archivo <code>.bin</code> merged correspondiente: <ul><li><strong>Archivo local</strong>: el binario recién compilado en tu equipo.</li><li><strong>Catálogo web</strong>: una versión ya publicada, si el instructor la agregó al catálogo del repositorio.</li></ul></li><li>Revisa la <strong>dirección de flash</strong> (<code>0x0000</code> por defecto) y la <strong>velocidad de carga</strong> (115200 baud es un valor seguro para empezar).</li><li>Da clic en <strong>Conectar ESP</strong> y selecciona el puerto que te ofrezca el navegador.</li><li>Da clic en <strong>Programar firmware</strong> y espera a que el progreso llegue a 100%.</li><li>Repite el proceso con las demás placas según la función asignada a cada una.</li></ol><h3 id="programacion-por-estaciones-varios-equipos-en-paralelo" tabindex="-1">Programación por estaciones (varios equipos en paralelo) <a class="header-anchor" href="#programacion-por-estaciones-varios-equipos-en-paralelo" aria-label="Permalink to &quot;Programación por estaciones (varios equipos en paralelo)&quot;">​</a></h3><p>En modo <strong>ESP32</strong> el panel ofrece una grilla de hasta <strong>10 estaciones</strong> para conectar y programar varias PULSAR ESP32-C6 a la vez desde una sola computadora — útil en la Etapa 1 del taller, cuando varias parejas programan su placa al mismo tiempo:</p><ol><li>Da clic en <strong>Conectar ESP</strong> dentro de cada estación para asignarle un dispositivo.</li><li>Usa <strong>Seleccionar conectados</strong> para marcar todas las estaciones con placa detectada.</li><li>Da clic en <strong>Programar seleccionados</strong> para cargar el mismo firmware en todas las estaciones marcadas en un solo paso.</li></ol><p>El resumen inferior (<strong>OK · SIN FLASH · ERROR</strong>) indica cuántas estaciones terminaron correctamente, y la consola <strong>esptool / ESP</strong> en la parte inferior del panel muestra el log en tiempo real — revísala si una carga falla o un dispositivo no queda en <strong>OK</strong>.</p><h2 id="vista-del-producto" tabindex="-1">Vista del producto <a class="header-anchor" href="#vista-del-producto" aria-label="Permalink to &quot;Vista del producto&quot;">​</a></h2><p>La carcasa de la PULSAR Stick está impresa en 3D y disponible en dos acabados de color; el hardware y las conexiones son idénticos en ambos casos.</p><table tabindex="0"><thead><tr><th></th><th>Variante roja</th><th>Variante beige</th></tr></thead><tbody><tr><td><strong>Frente</strong> — display OLED y botón BOOT</td><td><img src="'+e+'" alt="PULSAR Stick roja, frente"></td><td><img src="'+l+'" alt="PULSAR Stick beige, frente"></td></tr><tr><td><strong>Reverso</strong> — grabado de marca</td><td><img src="'+s+'" alt="PULSAR Stick roja, reverso"></td><td><img src="'+n+'" alt="PULSAR Stick beige, reverso"></td></tr><tr><td><strong>Con módulo LED Qwiic</strong> conectado</td><td><img src="'+c+'" alt="PULSAR Stick roja con LED Qwiic"></td><td><img src="'+p+'" alt="PULSAR Stick beige con LED Qwiic"></td></tr></tbody></table><p>La salida Qwiic (<code>SDA</code> pin 6, <code>SCL</code> pin 7) permite conectar módulos como el anillo de LEDs mostrado arriba para validar rápidamente el bus I²C antes de integrar los sensores propios del taller.</p>',37)])])}const L=r(g,[["render",m]]);export{P as __pageData,L as default};
